<?php
session_start(); require __DIR__.'/config.php';
if(empty($_SESSION['admin'])){header('Location: admin-login.php');exit;}
$db=getDb(); $success=''; $error=''; $month=preg_match('/^\d{4}-\d{2}$/',$_GET['month']??$_POST['award_month']??'')?($_GET['month']??$_POST['award_month']):date('Y-m'); $classYears=['C4C','C3C','C2C','C1C']; $uploadsDir=IMAGES_DIR;
function cotmFindAward(PDO $db,int $id):?array{$s=$db->prepare('SELECT * FROM cadet_of_month_awards WHERE id=?');$s->execute([$id]);$r=$s->fetch(PDO::FETCH_ASSOC);return $r?:null;}
function cotmEventName(?int $sid,string $class,string $name):string{return $sid===null?'Group Cadet of the Month — '.$name:'Cadet of the Month — '.$class.' — '.$name;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 try{
  if($action==='save_award'){
   $id=(int)($_POST['award_id']??0); $awardMonth=preg_match('/^\d{4}-\d{2}$/',$_POST['award_month']??'')?$_POST['award_month']:''; $raw=trim((string)($_POST['squadron_id']??'')); $sid=$raw===''?null:(int)$raw; $class=strtoupper(trim((string)($_POST['class_year']??''))); $name=trim((string)($_POST['cadet_name']??'')); $title=trim((string)($_POST['title']??'')); $desc=trim((string)($_POST['description']??'')); $points=($_POST['points_awarded']??'')!==''?(float)$_POST['points_awarded']:null;
   if(!$awardMonth)throw new RuntimeException('Select a valid award month.'); if($sid!==null&&!in_array($sid,array_map('intval',$db->query('SELECT id FROM squadrons')->fetchAll(PDO::FETCH_COLUMN)),true))throw new RuntimeException('Invalid squadron.'); if($sid===null)$class='GROUP';elseif(!in_array($class,$classYears,true))throw new RuntimeException('Invalid class year.'); if($name===''||$title===''||$desc==='')throw new RuntimeException('Cadet name, title/rank, and description are required.'); if($points===null||!is_finite($points))throw new RuntimeException('Enter a valid point value.');
   $existing=$id?cotmFindAward($db,$id):null; if($id&&!$existing)throw new RuntimeException('Award not found.');
   $photo=$existing['photo_filename']??null; $newPath=null; $oldPhoto=null;
   if(isset($_FILES['photo'])&&($_FILES['photo']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){[$valid,$ext]=validateUploadedImage($_FILES['photo']);if(!$valid)throw new RuntimeException($ext);if(!is_dir($uploadsDir)&&!mkdir($uploadsDir,0755,true)&&!is_dir($uploadsDir))throw new RuntimeException('Unable to create the image directory.');$photo='cadet-of-month-'.bin2hex(random_bytes(12)).'.'.$ext;$newPath=$uploadsDir.'/'.$photo;if(!move_uploaded_file($_FILES['photo']['tmp_name'],$newPath))throw new RuntimeException('Failed to save the uploaded cadet photo.');$oldPhoto=$existing['photo_filename']??null;}
   $now=date('c'); $db->beginTransaction();
   if($existing){
    if(!empty($existing['event_id'])){$s=$db->prepare('UPDATE events SET squadron_id=?,event_name=?,value=?,points_awarded=?,timestamp=? WHERE id=? AND event_type=?');$s->execute([$sid,cotmEventName($sid,$class,$name),$points,$points,$now,(int)$existing['event_id'],'cadet_of_month']);if($s->rowCount()===0)throw new RuntimeException('The linked scoring entry could not be updated.');}
    else{$s=$db->prepare('INSERT INTO events(squadron_id,event_type,event_name,value,points_awarded,timestamp,created_at) VALUES(?,?,?,?,?,?,?)');$s->execute([$sid,'cadet_of_month',cotmEventName($sid,$class,$name),$points,$points,$now,$now]);$eventId=(int)$db->lastInsertId();$s=$db->prepare('UPDATE cadet_of_month_awards SET event_id=? WHERE id=?');$s->execute([$eventId,$id]);}
    $s=$db->prepare('UPDATE cadet_of_month_awards SET award_month=?,squadron_id=?,class_year=?,cadet_name=?,title=?,description=?,photo_filename=?,points_awarded=?,updated_at=? WHERE id=?');$s->execute([$awardMonth,$sid,$class,$name,$title,$desc,$photo,$points,$now,$id]);
   }else{
    $s=$db->prepare('INSERT INTO events(squadron_id,event_type,event_name,value,points_awarded,timestamp,created_at) VALUES(?,?,?,?,?,?,?)');$s->execute([$sid,'cadet_of_month',cotmEventName($sid,$class,$name),$points,$points,$now,$now]);$eventId=(int)$db->lastInsertId();
    $s=$db->prepare('INSERT INTO cadet_of_month_awards(award_month,squadron_id,class_year,cadet_name,title,description,photo_filename,points_awarded,event_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$awardMonth,$sid,$class,$name,$title,$desc,$photo,$points,$eventId,$now,$now]);
   }
   $db->commit(); if($oldPhoto&&$newPath){$oldPath=$uploadsDir.'/'.basename($oldPhoto);if(is_file($oldPath))@unlink($oldPath);} $success=$existing?'Cadet of the Month award updated.':'Cadet of the Month award created.';
  }elseif($action==='delete_award'){
   $id=(int)($_POST['award_id']??0);$award=cotmFindAward($db,$id);if(!$award)throw new RuntimeException('Award not found.');$db->beginTransaction();if(!empty($award['event_id'])){$s=$db->prepare('DELETE FROM events WHERE id=? AND event_type=?');$s->execute([(int)$award['event_id'],'cadet_of_month']);}$s=$db->prepare('DELETE FROM cadet_of_month_awards WHERE id=?');$s->execute([$id]);$db->commit();if(!empty($award['photo_filename'])){$p=$uploadsDir.'/'.basename($award['photo_filename']);if(is_file($p))@unlink($p);}$success='Award removed and its scoring entry was removed from the existing events ledger.';
  }
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();if(!empty($newPath)&&is_file($newPath))@unlink($newPath);$error=$e instanceof PDOException&&strpos($e->getMessage(),'UNIQUE')!==false?'That award slot already exists for this month. Edit the existing award instead.':$e->getMessage();}
}
$squadrons=$db->query('SELECT * FROM squadrons ORDER BY id')->fetchAll(PDO::FETCH_ASSOC);$s=$db->prepare("SELECT a.*,s.name squadron_name FROM cadet_of_month_awards a LEFT JOIN squadrons s ON s.id=a.squadron_id WHERE a.award_month=? ORDER BY CASE WHEN a.squadron_id IS NULL THEN 0 ELSE 1 END,a.squadron_id,a.class_year");$s->execute([$month]);$awards=$s->fetchAll(PDO::FETCH_ASSOC);$map=[];foreach($awards as $a)$map[($a['squadron_id']===null?'group':$a['squadron_id']).':'.$a['class_year']]=$a;$monthLabel=date('F Y',strtotime($month.'-01'));
?>
