<style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f4f4f4;margin:0;padding:20px;color:#222}.container{max-width:1200px;margin:0 auto}h1{color:#002147;text-align:center;margin:5px 0}.subtitle{text-align:center;color:#666;margin:0 0 20px}.month-form{display:flex;justify-content:center;gap:10px;align-items:end;margin-bottom:20px;flex-wrap:wrap}.month-form label{font-weight:bold}.month-form input{display:block;margin-top:4px;padding:8px;border:1px solid #ccc;border-radius:4px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:18px;align-items:start}.panel{background:#fff;border-radius:8px;box-shadow:0 1px 5px rgba(0,0,0,.14);padding:18px}.panel h2{margin:0 0 14px;color:#002147;border-bottom:2px solid #002147;padding-bottom:8px}.slot{border:1px solid #ddd;border-radius:6px;padding:12px;margin:10px 0;background:#fafafa}.slot-title{display:flex;justify-content:space-between;gap:8px;align-items:center;color:#002147;font-weight:bold;margin-bottom:10px}.slot-title small{color:#666;font-weight:normal}label{display:block;font-weight:bold;margin-top:9px}input[type=text],input[type=number],input[type=month],textarea{width:100%;padding:8px;margin-top:4px;border:1px solid #ccc;border-radius:4px;font:inherit}textarea{min-height:90px;resize:vertical}button{padding:8px 12px;border:0;border-radius:4px;background:#002147;color:#fff;cursor:pointer;font-weight:bold}.danger{background:#b00020}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.success,.error{padding:12px;border-radius:5px;margin-bottom:16px}.success{background:#e8f5e9;color:#1a7a1a}.error{background:#ffebee;color:#b00020}.preview{display:flex;gap:10px;align-items:center;margin-top:8px;color:#666;font-size:.9rem}.preview img{width:60px;height:75px;object-fit:cover;border-radius:4px}.back{text-align:center;margin-top:22px}.back a{color:#002147;font-weight:bold;text-decoration:none}@media(max-width:600px){body{padding:12px}.grid{grid-template-columns:1fr}.panel{padding:14px}}</style></head>
