<?php if($a&&!empty($a['photo_filename'])):?><div class="preview"><img src="<?php echo htmlspecialchars(iconUrl($a['photo_filename']));?>" alt=""><span>Current photo will be kept unless replaced.</span></div><?php endif;?><div class="actions"><button type="submit"><?php echo $a?'Update Award':'Save Award';?></button><?php if($a):?><button class="danger" type="submit" name="action" value="delete_award" onclick="return confirm('Remove this award and its scoring entry?');">Remove</button><?php endif;?></div></form></div><?php endforeach;?></section><?php endforeach;?>
